INSERT INTO "ccg_inventory_items_import_tmp" VALUES(2,183,'CCG-694501','/api/inventory-image?key=inventory-items%2F2026-02-16%2Fa103456c-aeb2-423b-8e7c-dde0f942e8b4.jpg','Squire Electric Guitar & Amp','Packages','Squier','2010-2020','Bullet Stratocaster','Guess: White','Great Squier Fender Bullet Stratocaster electric guitar with Dean Markley bass amplifier + stand.',60,replace('Package was guitar, stand, strap, cord, amp, bag - total package.  I will change strings and sell for like $150 as a package.\n\nBought from a guy in south Littleton','\n',char(10)),1,1,195,'Worked hard to re-string, take video, and create boutique listing.  Sold SAME DAY to a kid in Highlands ranch for full price - I did bring it to him, so having transport in the listing was big.','2026-02-16 00:04:59','2026-02-23 17:03:14','2026-02-01',0,NULL,'2026-02-22T01:43:35.085Z','/api/inventory-image?key=inventory-items%2F2026-02-16%2Fa103456c-aeb2-423b-8e7c-dde0f942e8b4.jpg',195,NULL,0);
